// Generates the typed API schema from the backend's OpenAPI contract (docs/api/openapi.json, kept in sync with the
// controllers by OpenApiContractTest). `npm run api:generate` writes it; `npm run api:check` fails when it is stale.
import { readFile, writeFile } from 'node:fs/promises';
import { fileURLToPath } from 'node:url';
import openapiTS, { astToString } from 'openapi-typescript';

const contract = new URL('../../docs/api/openapi.json', import.meta.url);
const target = new URL('../src/api/schema.gen.ts', import.meta.url);
const header =
  '// GENERATED by `npm run api:generate` from docs/api/openapi.json - do not edit by hand.\n' +
  '// CI runs `npm run api:check`, which fails when this file no longer matches the contract.\n\n';

const generated = header + astToString(await openapiTS(contract));

if (process.argv.includes('--check')) {
  let current = '';
  try {
    current = await readFile(target, 'utf8');
  } catch {
    // missing file: reported as stale below
  }
  if (current !== generated) {
    console.error(
      `${fileURLToPath(target)} is stale: run \`npm run api:generate\` and commit the result.`,
    );
    process.exit(1);
  }
  console.log('API client is up to date with docs/api/openapi.json.');
} else {
  await writeFile(target, generated);
  console.log(`Wrote ${fileURLToPath(target)}`);
}
